import { z } from 'zod';

const PaymentResponseSchema = z.object({
  id: z.string(),
  amountCents: z.number(),
  status: z.enum(['succeeded', 'failed']),
});

type PaymentResponse = z.infer<typeof PaymentResponseSchema>;

async function fetchPayment(id: string): Promise<PaymentResponse> {
  const response = await fetch(`https://api.partner.example/payments/${id}`);
  const json = await response.json();
  return PaymentResponseSchema.parse(json); // lève une erreur si le contrat est rompu
}

